"""Responsive experimental preference inspector, with complete proof export."""
HTML=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>PLN Chess · Preference inspector</title><style>
:root{color-scheme:dark;--bg:#0c1320;--panel:#172235;--line:#34445e;--text:#edf3ff;--muted:#b4c3d9;--accent:#85dac4;--warn:#f4cf7a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:24px}nav{display:flex;gap:20px;flex-wrap:wrap}a{color:var(--accent)}h1{font-size:clamp(28px,5vw,42px);line-height:1.15;margin-bottom:12px}h2{font-size:21px;margin:0 0 14px}h3{font-size:17px;margin:10px 0}p{margin:8px 0}.lead{max-width:850px;color:var(--muted)}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:20px;margin:18px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.wide{grid-column:1/-1}label{display:block;color:var(--muted);font-size:14px}input,select,textarea,button{font:inherit;color:var(--text);background:#0d192a;border:1px solid #53647e;border-radius:6px;padding:10px;max-width:100%}input,select,textarea{width:100%;margin-top:6px}textarea{min-height:90px;resize:vertical}button{cursor:pointer;min-height:44px}button:hover{border-color:var(--accent)}button:disabled{opacity:.5;cursor:wait}.primary{background:var(--accent);color:#082c28;border:none;font-weight:700}.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-top:16px}.notice{border-left:4px solid var(--warn);padding-left:14px;color:var(--warn)}.status{padding:10px 0;color:var(--accent)}.error{color:#ffaaaa}.muted,small{color:var(--muted)}.metric{font-size:24px;font-weight:700}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{background:#0e1a2b;border:1px solid var(--line);border-radius:8px;padding:14px;overflow-wrap:anywhere}.board{display:grid;grid-template-columns:repeat(8,1fr);width:min(100%,380px);aspect-ratio:1;margin:auto;border:1px solid #64718a}.cell{border:0;border-radius:0;padding:0;min-height:0;background:#d6dfeb;color:#172133;font-size:clamp(23px,4vw,38px);position:relative}.cell.dark{background:#7189a4}.cell small{position:absolute;left:3px;bottom:1px;font-size:9px;color:#172133}.board-layout{display:grid;grid-template-columns:1fr 1fr;gap:18px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:9px;border-bottom:1px solid var(--line);vertical-align:top}td button{padding:7px;font-size:13px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,monospace;max-height:560px;overflow:auto;margin-bottom:0}details{margin:12px 0}summary{cursor:pointer;color:var(--accent)}.tags{display:flex;gap:8px;flex-wrap:wrap}.tag{border:1px solid var(--line);border-radius:20px;padding:3px 10px;font-size:13px}.proof-nav{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.hidden{display:none}@media(max-width:720px){main{padding:14px}.grid,.cards,.board-layout{grid-template-columns:1fr}.panel{padding:14px}.wide{grid-column:auto}h1{font-size:30px}.actions button{flex:1}.cell{font-size:32px}th,td{padding:7px}nav{font-size:14px}}
</style></head><body><main><nav><a href="/">Legal-move inspector</a><a href="/interactions">Fields and concepts</a></nav><header><p class="muted">PLN CHESS · CYCLE 13 · EXPERIMENTAL</p><h1>Compare consequences.<br>Inspect the evidence.</h1><p class="lead">Compare two supplied moves through separate legality beliefs, relational fields, learned preferences and bounded continuations.</p><p class="notice">A native conditional preference is a partial strategic argument. Raw confidence is not a probability of correctness. The inspector does not select or play moves.</p></header>
<section class="panel"><h2>Position and candidates</h2><form id="compare-form"><div class="grid"><label class="wide">Registered source position<select id="example" aria-label="Registered source position"></select></label><p class="wide muted" id="source"></p><label class="wide">FEN<input id="fen" required spellcheck="false"></label><label>Candidate A · UCI<input id="move-a" required pattern="[a-h][1-8][a-h][1-8][qrbn]?" spellcheck="false"></label><label>Candidate B · UCI<input id="move-b" required pattern="[a-h][1-8][a-h][1-8][qrbn]?" spellcheck="false"></label><label>Preference evidence<select id="model"><option value="relational">Relational fields</option><option value="full">Fields and limited concepts</option><option value="temporal">Immediate and continuation evidence</option><option value="empty">Empty model · evidence-removal control</option></select></label><label>Legal proof mode<select id="mode"><option>operational</option><option>strict</option><option>experimental</option></select></label></div><details><summary>Explicit responses and continuation scope</summary><p class="muted">Enter one or two lines per candidate. Each line contains an opponent reply and optional continuation, separated by spaces. The candidate above is prepended. Other responses remain unexamined.</p><div class="grid"><label>After candidate A<textarea id="responses-a" placeholder="Opponent reply, then our continuation"></textarea></label><label>After candidate B<textarea id="responses-b" placeholder="Opponent reply, then our continuation"></textarea></label></div><p id="response-source" class="muted"></p></details><details><summary>Observation gaps and work limits</summary><div class="grid"><label>Unknown squares · comma separated<input id="unknown" placeholder="e4, f5"></label><label>Proof nodes per stage<input id="budget" type="number" min="0" max="100000" value="100000"></label></div></details><div class="actions"><button class="primary" id="compare" type="submit">Compare moves</button><button id="continue" type="button">Inspect supplied continuations</button><button id="export" type="button" disabled>Export complete proof package</button></div><p id="status" class="status" role="status" aria-live="polite">Loading registered sources…</p></form></section>
<div id="results" hidden><section class="panel"><h2 id="verdict">Preference evidence</h2><p id="model-status" class="muted"></p><div id="channels" class="cards"></div><p id="scope" class="notice"></p><div id="comparison-controls" class="actions"></div><p id="legal"></p><div class="actions"><button id="preference-proof" type="button">Inspect preference rule and proof</button><button id="legal-proof" type="button">Inspect separate legality beliefs</button><button id="packet-proof" type="button">Inspect relative descriptor and provenance</button></div><details open><summary>Uncertainty and unexamined relationships</summary><div id="gaps"></div></details></section>
<section class="panel"><h2>Relational consequences</h2><div class="grid"><label>Inspect endpoint<select id="state"></select></label><p id="cost" class="muted"></p></div><div class="board-layout"><div><h3>Supplied root</h3><div id="before-board" class="board" aria-label="Supplied root board"></div></div><div><h3 id="state-title">Candidate endpoint</h3><div id="after-board" class="board" aria-label="Selected endpoint board"></div></div></div><p id="field-count" class="muted"></p><div class="table-wrap"><table><thead><tr><th>Field</th><th>Source → target</th><th>State</th><th>Strength</th><th>Confidence</th><th>Evidence</th></tr></thead><tbody id="relations"></tbody></table></div><button id="more" type="button">Show more relations</button><div class="actions"><button id="graph-proof" type="button">Inspect endpoint dependency graph</button><button id="change-proof" type="button">Inspect changes and persistence</button></div></section>
<section class="panel"><h2>Limited strategic concepts</h2><p class="muted">Structural candidates and learned packet conditionals are separate. Omitted candidates are not negative evidence.</p><div id="concepts" class="cards"></div></section><section class="panel" id="proof-section"><h2>Proof and provenance</h2><div class="proof-nav"><button id="proof-prev" type="button">Previous page</button><span id="proof-page"></span><button id="proof-next" type="button">Next page</button></div><pre id="proof">Choose a proof, field, descriptor or graph.</pre></section></div><footer class="muted"><p>Endpoint comparisons are host observations. Native PLN applies learned conditionals; it does not establish a joint strategic theorem, exhaustive response coverage or optimal play.</p></footer></main>
<script>
const $=id=>document.getElementById(id);let catalog=null,result=null,active=null,state=null,relationRows=[],shown=0,proofText='',proofPage=0,selected=null,resultText='';
const symbols={White:{King:'♔',Queen:'♕',Rook:'♖',Bishop:'♗',Knight:'♘',Pawn:'♙'},Black:{King:'♚',Queen:'♛',Rook:'♜',Bishop:'♝',Knight:'♞',Pawn:'♟'}};
function text(tag,value,parent,cls){const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;parent.append(e);return e}
function show(value){proofText=JSON.stringify(value,null,2);proofPage=0;proof();$('proof-section').scrollIntoView({behavior:'smooth',block:'start'})}
function proof(){const pages=Math.max(1,Math.ceil(proofText.length/18000));$('proof').textContent=proofText.slice(proofPage*18000,(proofPage+1)*18000);$('proof-page').textContent='Page '+(proofPage+1)+' of '+pages+' · full content in export';$('proof-prev').disabled=proofPage===0;$('proof-next').disabled=proofPage===pages-1}
function board(id,field){const box=$(id);box.replaceChildren();for(let y=7;y>=0;y--)for(let x=0;x<8;x++){const name=String.fromCharCode(97+x)+(y+1),piece=field?.pieces.find(p=>p.square[0]===x&&p.square[1]===y),unknown=field?.unknown_squares.some(s=>s[0]===x&&s[1]===y);const cell=text('button',unknown?'?':piece?symbols[piece.owner][piece.kind]:'',box,'cell'+((x+y)%2===0?' dark':''));cell.type='button';cell.setAttribute('aria-label',name+' '+(unknown?'unknown':piece?piece.owner+' '+piece.kind:'empty'));text('small',name,cell);cell.onclick=()=>show({square:name,piece,unknown,relations:(field?.relations||[]).filter(r=>r.source_square===name||r.target_square===name)})}}
function choose(){selected=catalog.examples[Number($('example').value)];$('fen').value=selected.fen;$('move-a').value=selected.moves[0];$('move-b').value=selected.moves[1];$('unknown').value='';$('responses-a').value=selected.branches?selected.branches.A.slice(1).join(' '):'';$('responses-b').value=selected.branches?selected.branches.B.slice(1).join(' '):'';$('source').textContent=selected.source+' · '+selected.split+' · source history supplied; historical legality remains unverified';$('response-source').textContent=selected.response_selection||'No registered continuation for this example. Explicit responses may be supplied above.';}
function renderComparison(row){active=row;const p=row.preference;$('verdict').textContent={'A-preferred':'Candidate A preferred','B-preferred':'Candidate B preferred',indeterminate:'Indeterminate comparison',incomplete:'Incomplete comparison'}[p.status];$('model-status').textContent=result.inspector_model.status+' · '+result.inspector_model.version.slice(0,16);$('channels').replaceChildren();for(const side of ['A','B','no-demonstrated-preference']){const c=p.channels[side],card=text('div','',$('channels'),'card');text('strong',side==='no-demonstrated-preference'?'No demonstrated preference':'Candidate '+side,card);text('p','Strength '+c.raw_stv.strength.toFixed(4),card,'metric');text('p','Raw confidence '+c.raw_stv.confidence.toFixed(4),card);text('small',c.classification,card)}$('scope').textContent=(p.conditional_proof_complete?'Native conditional proof available':'No complete native conditional application')+' · joint strategic proof incomplete · '+(row.horizon?'supplied horizon '+row.horizon:'immediate consequences');const legal=result.legality||result.immediate.legality;$('legal').textContent='Separate legality: A '+legal.A.classification+' · B '+legal.B.classification+'.';$('gaps').replaceChildren();for(const gap of p.gaps)text('p',gap,$('gaps'));if(result.unexamined_responses)text('p',result.unexamined_responses,$('gaps'));}
function more(){for(const r of relationRows.slice(shown,shown+100)){const tr=text('tr','',$('relations'));[r.family,r.source_square+' → '+r.target_square,r.classification,r.raw_stv.strength.toFixed(4),r.raw_stv.confidence.toFixed(4)].forEach(v=>text('td',v,tr));const b=text('button',r.conditional_proof_complete?'Native proof':'Inspect gaps',text('td','',tr));b.type='button';b.onclick=()=>show(r)}shown=Math.min(shown+100,relationRows.length);$('field-count').textContent=shown+' of '+relationRows.length+' relations displayed · full domain and proof traces in export';$('more').hidden=shown>=relationRows.length}
function renderState(){state=result.states[$('state').value];$('state-title').textContent=$('state').value;board('before-board',result.states.before?.field);board('after-board',state?.field);relationRows=state?.field.relations||[];shown=0;$('relations').replaceChildren();more();$('concepts').replaceChildren();for(const c of state?.concepts||[]){const card=text('div','',$('concepts'),'card');text('strong',c.concept+' · '+c.classification,card);text('p','S '+c.raw_stv.strength.toFixed(4)+' / C '+c.raw_stv.confidence.toFixed(4),card);text('small','Joint concept proof incomplete',card);const b=text('button','Inspect roles and proof',card);b.type='button';b.onclick=()=>show(c)}if(!state)text('p','Required endpoint is unavailable.',$('concepts'));}
function render(){ $('results').hidden=false;const controls=$('comparison-controls');controls.replaceChildren();const rows=result.comparisons||[{preference:result.preference,packet:result.packet}];if(result.comparisons){const b=text('button','Immediate consequences',controls);b.type='button';b.onclick=()=>renderComparison(result.immediate)}rows.forEach((row,i)=>{if(result.comparisons){const b=text('button','Ply '+row.horizon+' · A'+(row.branches.A+1)+' / B'+(row.branches.B+1),controls);b.type='button';b.onclick=()=>renderComparison(row)}});renderComparison(rows[rows.length-1]);$('state').replaceChildren();for(const name of Object.keys(result.states)){const o=text('option',name,$('state'));o.value=name}$('state').value=Object.keys(result.states).at(-1);$('cost').textContent=result.execution.native_invocations+' native operators · '+result.execution.elapsed_seconds.toFixed(2)+' s · '+result.execution.cache_hits+' cache hits';renderState();$('export').disabled=false;}
function responses(id,move){const lines=$(id).value.trim().split('\n').map(v=>v.trim()).filter(Boolean);return lines.length?lines.map(v=>[move,...v.split(/\s+/)]):[[move]]}
async function run(temporal){$('compare').disabled=true;$('continue').disabled=true;$('status').className='status';$('status').textContent='Computing separate native proofs…';try{const fen=$('fen').value.trim(),payload={fen,preference_model:$('model').value,mode:$('mode').value,max_invocations:Number($('budget').value),unknown_squares:$('unknown').value.split(',').map(v=>v.trim()).filter(Boolean)};if(selected&&selected.fen===fen)payload.history=selected.history;if(temporal){payload.branches={A:responses('responses-a',$('move-a').value.trim()),B:responses('responses-b',$('move-b').value.trim())};const registered=selected?.branches&&selected.fen===fen&&JSON.stringify(payload.branches)===JSON.stringify({A:[selected.branches.A],B:[selected.branches.B]});payload.selection_provenance=registered?selected.response_selection:'Explicit inspector input';payload.horizons=[2,3]}else{payload.move_a=$('move-a').value.trim();payload.move_b=$('move-b').value.trim()}const response=await fetch(temporal?'/cycle13-continuations':'/cycle13-compare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),raw=await response.text(),data=JSON.parse(raw);if(!response.ok)throw Error(data.error||'Inspection failed');result=data;resultText=raw;window.plnPreferenceResult=result;window.plnPreferenceResultRaw=raw;render();$('status').textContent=data.execution.truncated?'Incomplete work · inspect budgets and gaps':'Inspection finished · conditional evidence and uncertainty retained';}catch(error){$('status').className='status error';$('status').textContent='Error: '+error.message}finally{$('compare').disabled=false;$('continue').disabled=false}}
$('compare-form').onsubmit=e=>{e.preventDefault();run(false)};$('continue').onclick=()=>{if($('compare-form').reportValidity())run(true)};$('example').onchange=choose;$('state').onchange=renderState;$('more').onclick=more;$('preference-proof').onclick=()=>show(active.preference);$('packet-proof').onclick=()=>show(active.packet);$('legal-proof').onclick=()=>show(result.legal_inference||result.legal_inferences);$('graph-proof').onclick=()=>show(state?.graph);$('change-proof').onclick=()=>show(result.transitions||{fields:result.changes,concepts:result.concept_changes});$('proof-prev').onclick=()=>{proofPage--;proof()};$('proof-next').onclick=()=>{proofPage++;proof()};$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([resultText],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='pln-cycle13-preference-proofs.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)};
fetch('/cycle13-catalog').then(async r=>{const data=await r.json();if(!r.ok)throw Error(data.error||'Catalog unavailable');return data}).then(data=>{catalog=data;data.examples.forEach((row,i)=>{const o=text('option',row.id+(row.branches?' · supplied continuations':''),$('example'));o.value=i});choose();$('status').textContent='Ready · choose two candidates to inspect.'}).catch(e=>{$('status').textContent='Error: '+e.message});
</script></body></html>'''
